// First compare names lexicographically
if (lhs_name != rhs_name) {
    return lhs_name < rhs_name;
}

// If names are equal, compare partition points element-wise with epsilon tolerance
constexpr float kEpsilon = 1e-6;
size_t min_size = std::min(lhs_points.size(), rhs_points.size());

for (size_t i = 0; i < min_size; ++i) {
    float lhs_val = lhs_points[i];
    float rhs_val = rhs_points[i];

    if (std::abs(lhs_val - rhs_val) > kEpsilon) {
        return lhs_val < rhs_val;
    }
}

// If all compared points are equal up to epsilon, the shorter vector is considered smaller
return lhs_points.size() < rhs_points.size();

